    call: api.InputGroupCall,
    participant: *api.InputPeer,

    pub fn serialize(self: *const @This(), w: *Writer) TlError!void {
        try w.writeConstructorId(constructor_id);
        var flags: u32 = 0;
        if (self.report_spam) flags |= 1 << 0;
        try w.writeUInt(flags);
        try self.call.serialize(w);
        try self.participant.serialize(w);
    }
};

